#' @rdname as.data.table
#' @exportS3Method data.table::as.data.table
as.data.table.aucroc <- function(x, keep.rownames = FALSE, ...) {
  # A copy: the stored table must not be reachable for modification by
  # reference through the returned one
  data.table::copy(x[["uaucs"]])
}
